        netloc = host

    netloc_lower = netloc.lower() if netloc else ''

    if not netloc_lower or netloc_lower == ':':
        raise ValueError('uri has no host')

    if netloc_lower.startswith(':'):
        raise ValueError('uri has no host')

    if '@' in netloc_lower:
        netloc_lower = netloc_lower.split('@', 1)[1]

    if netloc_lower.startswith('['):
        bracket_end = netloc_lower.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        host_part = netloc_lower[:bracket_end + 1]
        port_part = netloc_lower[bracket_end + 1:]
        if port_part.startswith(':'):
            port_str = port_part[1:]
            if port_str == '':
                netloc_lower = host_part
            else:
                try:
                    port_num = int(port_str)
                except ValueError:
                    raise ValueError('invalid port: ' + port_str)
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('invalid port number: ' + str(port_num))
                default_ports = {'http': 80, 'https': 443}
                if scheme in default_ports and default_ports[scheme] == port_num:
                    netloc_lower = host_part
                else:
                    netloc_lower = host_part + ':' + str(port_num)
    else:
        if ':' in netloc_lower:
            parts = netloc_lower.rsplit(':', 1)
            host_part = parts[0]
            port_str = parts[1]

            if not host_part:
                raise ValueError('uri has no host')

            if port_str == '':
                netloc_lower = host_part
            else:
                try:
                    port_num = int(port_str)
                except ValueError:
                    raise ValueError('invalid port: ' + port_str)
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('invalid port number: ' + str(port_num))
                default_ports = {'http': 80, 'https': 443}
                if scheme in default_ports and default_ports[scheme] == port_num:
                    netloc_lower = host_part
                else:
                    netloc_lower = host_part + ':' + str(port_num)

    path = parsed.path
    if not path:
        path = '/'

    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@')

    result = scheme + '://' + netloc_lower + path

    return result
